const rows = $input.all();
if (!rows.length) return [];

const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Africa/Cairo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const map = Object.fromEntries(parts.map(p => [p.type, p.value]));
const today = `${map.year}-${map.month}-${map.day}`;

const cleanDate = (v) => String(v ?? '').trim().slice(0, 10);

const candidates = rows
  .filter(i => cleanDate(i.json.Publish_Date) >= today)
  .sort((a,b) => {
    const ad = cleanDate(a.json.Publish_Date);
    const bd = cleanDate(b.json.Publish_Date);
    if (ad !== bd) return ad.localeCompare(bd);
    return Number(a.json.row_number || 0) - Number(b.json.row_number || 0);
  });

return candidates.length ? [candidates[0]] : [];

const src = $json;
const text = [src['Post Description'],src.Content_Pillar,src.Strategy,src.Notes,src.Image_Text,src.Image_Prompt].filter(Boolean).join(' ').toLowerCase();
const rules={
 personal:['تعلمت','رأيي','خبرتي','من واقع','موقف','شفت','قابلت','درس','تجربتي','personal','lesson','experience'],
 expansion:['توسع','فرع','فروع','expand','expansion','scale','scaling','نمو','كبر'],
 profitability:['ربح','ربحية','هامش','margin','profit','مكسب','تكلفة البيع','مبيعات'],
 cashflow:['كاش','سيولة','cash','تحصيل','receivable','دفع','مخزون','التزامات'],
 pricing:['تسعير','سعر','pricing','خصم','discount','عرض سعر'],
 operations:['تشغيل','عملية','عمليات','operations','workflow','فريق','إنتاجية','اختناق'],
 decision:['قرار','اختيار','عشوائ','decision','مخاطرة','risk','أقرر','تقرر'],
 diagnostic:['تشخيص','سبب','مشكلة','diagnos','root cause','قبل الحل','تحليل']
};
let best='diagnostic',bestScore=-1;
for(const [type,words] of Object.entries(rules)){const s=words.reduce((a,w)=>a+(text.includes(w)?1:0),0);if(s>bestScore){best=type;bestScore=s;}}
const presets={
 decision:{label:'قرار إداري',mood:'bright strategic contrast',title:'القرار قبل التنفيذ',subhead:'الاختيار السريع قد تكون له تكلفة طويلة.',benefits:['قرار أوضح','مخاطرة أقل','هدر أقل','نمو أهدأ'],scene:'a clear business decision metaphor: one protagonist facing two distinct strategic paths, one chaotic and costly and one structured and sustainable'},
 expansion:{label:'قرار توسع',mood:'bright optimistic architectural',title:'قبل ما تتوسع',subhead:'التوسع الجيد يبدأ من أساس يتحمل النمو.',benefits:['اختبار الطلب','حساب السيولة','جاهزية التشغيل','توسع محسوب'],scene:'a business expansion metaphor with a small successful operation in the foreground and multiple possible expansion paths, one disciplined path leading to sustainable growth'},
 profitability:{label:'ربحية',mood:'bright analytical premium',title:'مش كل بيع مكسب',subhead:'ارتفاع المبيعات لا يعني بالضرورة ارتفاع الربح.',benefits:['هامش أقوى','تكلفة أوضح','بيع أذكى','ربح حقيقي'],scene:'a premium business profitability metaphor where sales activity is rising while profit margin is being squeezed, shown through physical business objects and clean abstract unlabeled charts'},
 cashflow:{label:'سيولة',mood:'bright financial tension',title:'الكاش أهم من الرقم',subhead:'المبيعات على الورق لا تدفع الالتزامات وحدها.',benefits:['تحصيل أسرع','مخزون أذكى','التزام أقل','سيولة أفضل'],scene:'a cash-flow metaphor with money moving through a clean business pipeline while receivables, inventory and obligations create visible bottlenecks'},
 pricing:{label:'تسعير',mood:'bright commercial clarity',title:'السعر قرار',subhead:'التسعير ليس رقمًا منفصلًا عن القيمة والتكلفة.',benefits:['قيمة أوضح','هامش أفضل','خصم أقل','قرار أسرع'],scene:'a refined pricing strategy metaphor using product value, cost and margin as physical balanced elements in a premium business setting'},
 operations:{label:'تشغيل',mood:'bright operational precision',title:'التشغيل يكشف الحقيقة',subhead:'النمو بدون نظام يحوّل الضغط إلى فوضى.',benefits:['تدفق أسرع','اختناق أقل','فريق أوضح','جودة أعلى'],scene:'a modern SME operations metaphor with a workflow moving from cluttered bottleneck into a clean organized process, realistic office or light industrial context'},
 diagnostic:{label:'تشخيص أعمال',mood:'bright consulting editorial',title:'التشخيص قبل الحل',subhead:'السؤال الأدق يختصر حلولًا كثيرة خاطئة.',benefits:['سبب أوضح','قرار أدق','هدر أقل','خطوة عملية'],scene:'an editorial business diagnostic scene: consultant and business owner studying evidence, numbers and root causes before making a decision'},
 personal:{label:'خبرة استشارية',mood:'bright human editorial',title:'درس من الشغل',subhead:'الخبرة الحقيقية تبدأ من مواقف وقرارات واقعية.',benefits:['خبرة عملية','وجهة نظر','قرار أوضح','تعلم أسرع'],scene:'a premium editorial personal-brand scene from a consultant perspective, over-the-shoulder or side-profile in a real working moment, no attempt to imitate a specific real person'}
};
const p=presets[best];
let title=String(src.Image_Text||'').trim();
if(!title||title.length>38) title=p.title;
if(text.includes('عشوائ')) title='العشوائية لها تكلفة';
if(text.includes('فرع')||text.includes('توسع')) title='قبل ما تتوسع';
if((text.includes('مبيعات')||text.includes('بيع'))&&(text.includes('ربح')||text.includes('مكسب'))) title='مش كل بيع مكسب';
const variants=[
 'wide environmental editorial composition with a strong foreground subject and depth',
 'high-end side-angle editorial composition with one dominant metaphor',
 'clean top-down or elevated business composition with structured visual hierarchy',
 'architectural symbolic composition with clear depth and one visual focal point'
];
return [{json:{...src,Visual_Type:best,Visual_Label:p.label,Visual_Mood:p.mood,Image_Title_Final:title,Visual_Subhead:p.subhead,B1:p.benefits[0],B2:p.benefits[1],B3:p.benefits[2],B4:p.benefits[3],Visual_Scene:p.scene,Composition_Variant:variants[Number(src.row_number||1)%4],Strategy_Version:'V4.0'}}];

const items=$input.all();
if(!items.length) throw new Error('No image returned from generator');
for(const item of items){if(!item.binary||!item.binary.image) throw new Error('Image generation returned no binary image');}
return items;

